    id: "cons-2019-hl-q5-c", topicId: "cons-6-1", conceptId: "proposed-upgrade-thermal-properties-above-wall",
    section: "B", questionRef: "2019 HL Q5(c)",
    stem: "The external wall of a house built in the 1990s is of 100 mm concrete block construction with a 100 mm partially filled cavity, as shown.",
    questionText: "It is proposed to upgrade the thermal properties of the above wall, to meet the Passive House standard, by fixing expanded polystyrene to the external surface, as shown. Given the thermal conductivity (k) of expanded polystyrene as 0.031 W/m°C, calculate the thickness of expanded polystyrene required to achieve a U-value of 0.15 W/m2 °C.",
    tariffModel: {"kind":"fixed"}, totalMarks: 15,
    rows: [
    { id: "required-resistance", kind: "criterion", verbatim: "Resistance for U- value for 0.15Wm2K (using R=1/U)", marks: 3, contextNote: "Required resistance = 1 ÷ 0.15 = 6.666 m²K/W.", permittedMarks: [0,1,2,3] },
    { id: "existing-resistance", kind: "criterion", verbatim: "Resistance from calculated U-value from part (a)", marks: 3, contextNote: "Existing resistance = 1 ÷ 0.516 = 1.939 m²K/W (the scheme prints the divisor as 0.156).", permittedMarks: [0,1,2,3] },
    { id: "difference", kind: "criterion", verbatim: "Difference in resistances (required resistance)", marks: 3, contextNote: "Difference = 6.666 − 1.939 = 4.727 m²K/W.", permittedMarks: [0,1,2,3] },
    { id: "formula", kind: "criterion", verbatim: "Application of formula R = T/k", marks: 3, contextNote: "R = T/k, so 4.727 = T/0.031.", permittedMarks: [0,1,2,3] },
    { id: "thickness", kind: "criterion", verbatim: "Required thickness of insulation", marks: 3, contextNote: "T = 4.727 × 0.031 = 0.146537 m: 147 mm of expanded polystyrene (146 or 147 mm accepted).", permittedMarks: [0,1,2,3] },
    ],
